def install_guards() -> None:
    op.execute("""
    CREATE FUNCTION p4_customer_immutable() RETURNS trigger
    LANGUAGE plpgsql AS $$
    BEGIN
      IF (NEW.company_id, NEW.company, NEW.address_one, NEW.address_two,
          NEW.city, NEW.state, NEW.zip) IS DISTINCT FROM
         (OLD.company_id, OLD.company, OLD.address_one, OLD.address_two,
          OLD.city, OLD.state, OLD.zip) THEN
        RAISE EXCEPTION 'Original customer address is immutable'
          USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END $$""")
    op.execute(
        "CREATE TRIGGER customer_immutable BEFORE UPDATE ON customers "
        "FOR EACH ROW EXECUTE FUNCTION p4_customer_immutable()"
    )
    op.execute("""
    CREATE FUNCTION p4_shipment_immutable() RETURNS trigger
    LANGUAGE plpgsql AS $$
    BEGIN
      IF (NEW.shipper_company_id, NEW.shipper_ref, NEW.sender_id,
          NEW.recipient_id, NEW.carrier_company_id, NEW.account_id,
          NEW.creation_service, NEW.created_at) IS DISTINCT FROM
         (OLD.shipper_company_id, OLD.shipper_ref, OLD.sender_id,
          OLD.recipient_id, OLD.carrier_company_id, OLD.account_id,
          OLD.creation_service, OLD.created_at) THEN
        RAISE EXCEPTION 'Original shipment fields are immutable'
          USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END $$""")
    op.execute(
        "CREATE TRIGGER shipment_immutable BEFORE UPDATE ON shipments "
        "FOR EACH ROW EXECUTE FUNCTION p4_shipment_immutable()"
    )
    op.execute("""
    CREATE FUNCTION p4_number_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      PERFORM pg_advisory_xact_lock(hashtextextended('shipment-numbers', 0));
      RETURN NEW;
    END $$""")
    op.execute(
        "CREATE TRIGGER shipment_number_guard BEFORE INSERT OR UPDATE "
        "OF shipment_number ON shipments FOR EACH ROW "
        "EXECUTE FUNCTION p4_number_guard()"
    )
